from scipy.optimize import least_squares
def sim(p,U,x0,Yf=None):
    a,b,c,d,e,L=p[:6]
    x=x0; xs=[x]
    for t in range(len(U)):
        x=a*x+b*U[t,0]+c*U[t,1]+d+e*(Yf[t,1] if Yf is not None else 0)
        xs.append(x)
    return np.array(xs)
def res(p,mode):
    xs=sim(p,U,p[6],Yf if mode else None)
